/// Every guest-plane tag.
#[allow(clippy::large_enum_variant, reason = "one variant per tag, each the tag's own fields")]
#[derive(Debug, Clone, PartialEq)]
pub enum GuestLine {
    GuestTraceOpened(GuestTraceOpened),
    GuestThreadStarted(GuestThreadStarted),
    GuestCallReturned(GuestCallReturned),
    GuestThreadStateObserved(GuestThreadStateObserved),
    GuestTraceClosed(GuestTraceClosed),
}

impl GuestLine {
    /// The event for `tag`, from a line's keys; the `tag` key itself is not a field.
    pub fn from_tag(tag: &str, fields: &Map<String, Value>) -> Result<Self, FieldError> {
        match tag {
            "GUEST_TRACE_OPENED" => GuestTraceOpened::from_fields(fields, Some("tag")).map(GuestLine::GuestTraceOpened),
            "GUEST_THREAD_STARTED" => GuestThreadStarted::from_fields(fields, Some("tag")).map(GuestLine::GuestThreadStarted),
            "GUEST_CALL_RETURNED" => GuestCallReturned::from_fields(fields, Some("tag")).map(GuestLine::GuestCallReturned),
            "GUEST_THREAD_STATE_OBSERVED" => GuestThreadStateObserved::from_fields(fields, Some("tag")).map(GuestLine::GuestThreadStateObserved),
            "GUEST_TRACE_CLOSED" => GuestTraceClosed::from_fields(fields, Some("tag")).map(GuestLine::GuestTraceClosed),
            _ if DEPRECATED_TAGS.contains(&tag) => Err(FieldError::new("tag", format!("{tag:?} is deprecated in vocabulary {VOCAB_VERSION}"))),
            _ => Err(FieldError::new("tag", format!("{tag:?} is not a guest-plane tag"))),
        }
    }

    pub fn tag(&self) -> &'static str {
        match self {
            GuestLine::GuestTraceOpened(_) => GuestTraceOpened::TAG,
            GuestLine::GuestThreadStarted(_) => GuestThreadStarted::TAG,
            GuestLine::GuestCallReturned(_) => GuestCallReturned::TAG,
            GuestLine::GuestThreadStateObserved(_) => GuestThreadStateObserved::TAG,
            GuestLine::GuestTraceClosed(_) => GuestTraceClosed::TAG,
        }
    }

    pub fn line(&self) -> String {
        match self {
            GuestLine::GuestTraceOpened(e) => guest_line(e),
            GuestLine::GuestThreadStarted(e) => guest_line(e),
            GuestLine::GuestCallReturned(e) => guest_line(e),
            GuestLine::GuestThreadStateObserved(e) => guest_line(e),
            GuestLine::GuestTraceClosed(e) => guest_line(e),
        }
    }
}

